<section class="container mail-heading"><div><span class="eyebrow">TIDALWAVE MAIL</span><h1>A little less noise<span>.</span></h1><p><?= isset($account)?e($account['address']):'Your private space for conversations.' ?></p></div><?php if(isset($account)): ?><a class="button primary" href="/mail/compose">+ Compose</a><?php endif ?></section>
<?php if(isset($mailError)): ?><section class="container mail-error"><h2>Mailbox unavailable</h2><p role="alert"><?= e($mailError) ?></p><div class="button-row"><a class="button primary" href="/account">Your account</a><a class="button secondary" href="/mail">Return to mailbox</a></div><?php if(!empty($unsent)): ?><h3>Your unsent text</h3><p>Copy this text before leaving. Reattach files when retrying.</p><pre><?= e(($unsent['to']??'')."\n".($unsent['subject']??'')."\n\n".($unsent['body']??'')) ?></pre><?php endif ?></section>
<?php else: ?>
<section class="container mail-shell"><aside class="mail-sidebar"><span class="eyebrow">YOUR MAILBOX</span><nav aria-label="Mail folders"><?php foreach($folders as $f): ?><a href="/mail?folder=<?= urlencode($f['id']) ?>" <?= $f['id']===$selected?'aria-current="page"':'' ?>><span><?= e(ucfirst($f['role']?:$f['name'])) ?></span><small><?= (int)$f['unreadEmails'] ?></small></a><?php endforeach ?></nav><details><summary>+ New folder</summary><form method="post" action="/mail/folder"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><label class="sr-only" for="folder-name">Folder name</label><input id="folder-name" name="name" maxlength="80" required placeholder="Folder name"><button class="button secondary">Create</button></form></details><div class="mail-storage"><span><?= (int)$account['quota_mb'] ?> MB storage limit</span><p>Private mailbox<br>Linked to your Discord account</p></div></aside>
<div class="mail-content"><?php if($notice): ?><p class="account-notice" role="status"><?= e($notice) ?></p><?php endif ?>
<?php if(!$config['external_delivery']): ?><p class="mail-status">Internal mail available · External delivery awaiting DNS / provider setup</p><?php endif ?>
<?php if($compose): ?><form class="mail-compose" method="post" action="/mail/compose" enctype="multipart/form-data"><h2><?= $draft?'Edit draft':'New message' ?></h2><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="send_nonce" value="<?= e($_SESSION['mail_send_nonce']) ?>"><input type="hidden" name="draft" value="<?= e($draft['id']??'') ?>"><p>From: <?= e($account['address']) ?></p><label>To<input name="to" maxlength="5000" value="<?= e(implode(', ',array_column($draft['to']??[],'email'))) ?>" placeholder="name@example.com"></label><label>Cc<input name="cc" maxlength="5000" value="<?= e(implode(', ',array_column($draft['cc']??[],'email'))) ?>"></label><label>Subject<input name="subject" maxlength="300" value="<?= e($draft['subject']??'') ?>" placeholder="What’s on your mind?"></label><label class="sr-only" for="mail-body">Message</label><textarea id="mail-body" name="body" rows="15" maxlength="200000" placeholder="Write your message…"><?= e($draft?Webmail::text($draft):'') ?></textarea><?php if(!empty($draft['attachments'])): ?><p><?= count($draft['attachments']) ?> saved attachment(s) will be kept.</p><?php endif ?><label>Attachments · 5 MB each, up to 5<input type="file" name="attachments[]" multiple></label><div class="button-row"><button class="button primary" name="action" value="send">Send message ↗</button><button class="button secondary" name="action" value="draft">Save draft</button></div></form>
<?php elseif($message): ?><article class="mail-message"><a href="/mail?folder=<?= urlencode($selected) ?>">← Back to messages</a><h2><?= e($message['subject']?:'(No subject)') ?></h2><p><strong><?= e(implode(', ',array_column($message['from']??[],'email'))) ?></strong><br>To: <?= e(implode(', ',array_column($message['to']??[],'email'))) ?></p><small><?= e($message['receivedAt']) ?></small><pre class="mail-body"><?= e(Webmail::text($message)) ?></pre><?php foreach($message['attachments']??[] as $a): ?><a class="mail-attachment" href="/mail/download?message=<?= urlencode($message['id']) ?>&amp;blob=<?= urlencode($a['blobId']) ?>">↓ <?= e($a['name']??'Attachment') ?></a><?php endforeach ?><div class="mail-actions"><?php if(!empty($message['keywords']['$draft'])): ?><a class="button primary" href="/mail/compose?draft=<?= urlencode($message['id']) ?>">Edit draft</a><?php endif ?><form method="post" action="/mail/move"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="message" value="<?= e($message['id']) ?>"><label>Move to<select name="folder"><?php foreach($folders as $f): ?><option value="<?= e($f['id']) ?>"><?= e(ucfirst($f['role']?:$f['name'])) ?></option><?php endforeach ?></select></label><button class="button secondary">Move</button></form></div></article>
<?php else: ?><form class="mail-search" method="get" action="/mail"><input type="hidden" name="folder" value="<?= e($selected) ?>"><label class="sr-only" for="mail-search">Search email</label><input id="mail-search" name="q" value="<?= e($search) ?>" maxlength="200" placeholder="Search this folder…"><button class="button secondary">Search</button></form><div class="mail-list-heading"><h2><?php foreach($folders as$f)if($f['id']===$selected)echo e(ucfirst($f['role']?:$f['name'])); ?></h2><span><?= (int)$total ?> messages</span></div><div class="mail-list"><?php foreach($emails as$email): ?><a class="mail-row <?= empty($email['keywords']['$seen'])?'unread':'' ?>" href="/mail?folder=<?= urlencode($selected) ?>&amp;message=<?= urlencode($email['id']) ?>"><span class="mail-avatar"><?= e(mb_strtoupper(mb_substr($email['from'][0]['name']??$email['from'][0]['email']??'?',0,1))) ?></span><span class="mail-row-copy"><strong><?= e(($email['from'][0]['name']??'')?:($email['from'][0]['email']??'Unknown sender')) ?></strong><span><?= e($email['subject']?:'(No subject)') ?><?= $email['hasAttachment']?' · Attachment':'' ?></span><small><?= e($email['preview']) ?></small></span><time><?= e(substr($email['receivedAt'],0,10)) ?></time></a><?php endforeach ?><?php if(!$emails): ?><div class="mail-empty"><span>✦</span><h3>All clear.</h3><p><?= $search?'No messages match your search.':'No messages in this folder yet.' ?></p></div><?php endif ?></div><nav class="button-row pagination" aria-label="Message pages"><?php if($page>1): ?><a class="button secondary" href="?folder=<?= urlencode($selected) ?>&amp;q=<?= urlencode($search) ?>&amp;page=<?= $page-1 ?>">Previous</a><?php endif ?><?php if($page*30<$total): ?><a class="button secondary" href="?folder=<?= urlencode($selected) ?>&amp;q=<?= urlencode($search) ?>&amp;page=<?= $page+1 ?>">Next</a><?php endif ?></nav><?php endif ?></div></section><?php endif ?>
